"""Personality and grammatical identity do not depend on the selected voice."""
import re


def action_context(text, history):
    if len(text) > 250 or re.search(r"\b(?:напиши|сочини|придумай|рассказ|сцену|ролевая)\b", text, re.I):
        return False
    vocabulary = r"музык|плеер|проигр|программ|браузер|запуст|включ|откро|аимп|песн|трек|любим|лайк|пауза|задач|напомин|напомн|таймер|будильник|\bimp\b"
    return bool(re.search(vocabulary, text, re.I) or (len(text.split()) <= 4 and history and re.search(vocabulary, history[-1]["content"], re.I)))


def without_unexecuted_claims(text):
    # Used only on ordinary short control-related replies, before any text/TTS leaves the core.
    if re.search(r"(?:создал[аи]?|добавил[аи]?|удалил[аи]?|перен[её]с(?:ла)?|поставил[аи]?|завершил[аи]?)\s+.{0,60}(?:задач|напомин|таймер|будильник)|(?:задач\w*|напомин\w*|таймер\w*|будильник\w*)\s+(?:создан|добавлен|удален|перенесен|установлен|завершен)", text, re.I):
        return "Задачи и напоминания в этом ответе не изменялись. Используйте явную команду или включите понимание свободных просьб о задачах в настройках."
    if re.search(r"\bнайден[оаы]?\b|\b(?:воспроизведение|проигрывание)\s*[:—]|\b(?:песн\w*|трек\w*)\s+(?:запущен|включен|играет|воспроизводится)", text, re.I):
        return "Поиск и запуск песни в этом ответе не выполнялись. Чтобы проверить результат в плеере, назовите песню и исполнителя: «найди песню …»."
    if re.search(r"проверк\w*\s+(?:плеер\w*|проигрывател\w*)\s+(?:завершен|выполнен)|проверенн\w*\s+статус", text, re.I):
        return "Состояние плеера в этом ответе не проверялось. Скажите «проверь проигрыватель»; для Яндекс Музыки сначала настройте подключение в разделе «Команды»."
    if re.search(r"\b(?:(?:добавил[аи]?|убрал[аи]?|удалил[аи]?)\s+.{0,35}(?:любим|избран)|(?:поставил[аи]?|снял[аи]?)\s+лайк)", text, re.I):
        return "Избранное в этом ответе не изменялось. Подключите Яндекс Музыку в разделе «Команды» и скажите «добавь в любимые» или «убери из любимых»."
    if re.search(r"\b(?:проверил[аи]?|проверю|проверяю|наш[её]л|нашла|обнаружил[аи]?)\b", text, re.I):
        return "Проверка Windows в этом ответе не выполнялась. Для настоящей проверки скажите «проверь Яндекс Браузер» или назовите другое приложение."
    if re.search(r"\b(?:запускаю|запустил[аи]?|открываю|открыл[аи]?|включил[аи]?|выключил[аи]?|включу|выключу|открою|поставил[аи]?\s+.{0,50}на паузу)|музыка\s+(?:запущена|включена|началась)|запускаю\s+«", text, re.I):
        return "Команда Windows в этом ответе не выполнялась. Уточните, что открыть или какое действие выполнить. Для плеера можно сказать «поставь музыку на паузу», «продолжи музыку» или «проверь проигрыватель»."
    return text


def local_result(text, gender):
    """Only adapt fixed result prefixes, never quoted notes or model output."""
    if gender == "masculine":
        return text
    feminine = {"Запомнил": "Запомнила", "Создал": "Создала", "Удалил": "Удалила", "Передал": "Передала", "Перенёс": "Перенесла", "Отменил": "Отменила", "Отметил": "Отметила", "Не нашёл": "Не нашла", "Не распознал": "Не распознала"}
    neutral = {"Создал встречу": "Создана встреча", "Создал заметку": "Создана заметка", "Удалил событие": "Удалено событие", "Перенёс встречу": "Перенесена встреча", "Передал браузеру": "Команда передана браузеру", "Передал Windows": "Команда передана Windows", "Запомнил": "Запись сохранена", "Перенёс": "Перенесено:", "Отменил": "Отменено:", "Отметил выполненной задачу": "Выполнена задача", "Не нашёл": "Не удалось найти", "Не распознал": "Не удалось распознать"}
    prefixes = feminine if gender == "feminine" else neutral
    for source, target in prefixes.items():
        changed, count = re.subn(r"^(\d+\. )?" + re.escape(source) + r"\b", lambda match: (match[1] or "") + target, text, count=1)
        if count:
            return changed
    return text


def prompt(settings, mode="text"):
    gender = {
        "feminine": "Говори о себе в женском роде: «я готова», «я поняла», «я сопоставила». Не перенимай мужской род из старых ответов. Род пользователя не меняй.",
        "masculine": "Говори о себе в мужском роде: «я готов», «я понял», «я сопоставил». Род пользователя не меняй.",
        "neutral": "Говори о себе без указания рода: «я могу», «готово», «получилось». Избегай родовых форм о себе. Род пользователя не меняй.",
    }[settings.grammatical_gender]
    result = settings.personality[:3000] + "\nИмя ассистента: " + settings.name + "\n" + gender
    if mode == "conversation":
        result += "\nСейчас идёт разговор голосом. Обычно отвечай одной-тремя естественными короткими фразами, без Markdown и постоянных встречных вопросов. Подробности давай по просьбе."
    return result + (
        "\nДоступны локальные команды открытия, звук Windows, заметки, задачи, документы и память. Не выдумывай выполненные действия и воспоминания. "
        "Команды звука: «громкость 35 процентов», «сделай тише», «выключи звук», «включи звук», «следующий трек», «поставь музыку на паузу», «продолжи музыку», «проверь проигрыватель». Плеер проверяется отдельным инструментом. В этом генерируемом ответе инструменты не выполняются; старые утверждения в истории не подтверждают новых действий. "
        "Без результата команды звука не утверждай, что изменил громкость, выключил звук или переключил музыку. Если просьба искажена распознаванием речи, уточни её, не выдумывай действие. "
        "Память сохраняется явной командой или после принятия предложения. Произвольный текст твоего ответа не исполняется. "
        "Напоминания: «напомни ежедневно в 10 проверить почту», «напомни по понедельникам и средам в 9 зарядка». По будням — понедельник–пятница без учёта праздников. "
        "Перенос недавнего повторяющегося напоминания меняет время всей серии; «отмени повтор» оставляет ближайший срок однократным, «отмени напоминание» удаляет всю запись. "
        "Старые записи можно выбрать по названию и сроку: «найди напоминание купить хлеб на завтра», «перенеси напоминание купить хлеб на 11», «удали задачу проверить сборку». При нескольких совпадениях нужен номер записи. Поиск ограничен текущим пространством. "
        "Уведомления приходят, пока программа работает, включая трей. Без результата локальной команды не утверждай, что создал или изменил задачу. "
        "Веб-поиск нужен по явной просьбе; без его результатов не заявляй, что проверил свежие сведения. Почта, камера, умный дом и синхронизация календаря не подключены."
        "\nЛокальный календарь: «создай встречу Обзор завтра в 10 на 30 минут», «покажи расписание на неделю», «перенеси встречу на 11», «отмени встречу». "
        "По умолчанию встреча длится час, напоминание выключено. «Напомни о встрече за 15 минут» включает напоминание. Перенос и отмена относятся к недавнему событию этого чата. "
        "Без результата локальной команды не утверждай, что изменил событие."
    )
